mapper.select:
select 
  from pep_agent.investigation_task
 where project_id = #{projectId}
   and (owner_id = #{ownerId} or #{allRead} = true)

   and status = #{status}

 order by updated_at desc, id desc
 limit #{limit}

mapper.update:
update pep_agent.investigation_task
   set status = #{status}, version = version + 1, updated_at = now()
 where id = #{id} and version = #{expectedVersion}

mapper.select:
select id, task_id as taskId, seq, type, payload, actor_id as actorId, created_at as createdAt
  from pep_agent.task_event
 where task_id = #{taskId} and seq > #{afterSeq}
 order by seq
 limit #{limit}

select count(*) from pep_agent.task_evidence
 where task_id = #{taskId}
   and evidence_id in

